import{z as o,x as p,o as t,c as s,q as n,j as i,D as e,d as E,s as l,S as r,b as A}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"从存货模型到实盘参数","description":"","frontmatter":{"title":"从存货模型到实盘参数","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/mm-floor-to-practice.md","filePath":"quant/mm-floor-to-practice.md","lastUpdated":1791063341000}'),m={name:"quant/mm-floor-to-practice.md"};function d(F,a,D,c,h,u){const B=p("Mermaid");return t(),s("div",null,[a[2]||(a[2]=n('<h1 id="从存货模型到实盘参数" tabindex="-1">从存货模型到实盘参数 <a class="header-anchor" href="#从存货模型到实盘参数" aria-label="Permalink to &quot;从存货模型到实盘参数&quot;">​</a></h1><div class="epigraph"><p>模型给的是分解，不是四个数字；实盘的宽度与偏度是校准和灰度出来的配置，参数填错了，闭式解越漂亮，亏得越整齐。</p><footer>—— 据 Avellaneda and Stoikov, Quantitative Finance, 2008；Guéant, Lehalle and Fernandez-Tapia, 2013 与生产做市实践整理</footer></div><p><a href="/quant/obd-map">上一课</a>把订单簿动力学收成一张地图：状态、速率与机制互相约束，统计清单先于模型、条件化先于平均、闭环意识贯穿始终，并把速率方程与冲击函数交给做市与执行的深化课程。本课是「做市业务深入」的第一课，接走那台引擎：把「按库存偏移报价、按波动开价差」变成会挂单的配置。主干已把理论讲完：<a href="/quant/ho-stoll-inventory">Ho–Stoll</a> 给出存货偏度，<a href="/quant/avellaneda-stoikov">Avellaneda–Stoikov</a> 把报价写成无差异价格加最优价差，<a href="/quant/glft-market-making">GLFT</a> 去掉剩余时间因子。本课不再推公式，只问：公式里的 \\(\\gamma,\\sigma,\\kappa,A\\) 与惩罚系数从哪来，又如何知道填错了。后课默认这些模型已读。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>理论到实盘隔着一条参数缝。强度 \\(\\lambda(\\delta)=A e^{-\\kappa\\delta}\\) 里的 \\(A\\) 与 \\(\\kappa\\) 概括市价单对距离的弹性，不是从一档深度读出的物理常数；\\(\\sigma\\) 是中间价的扩散系数，隔夜跳空与尾盘放大使它全天不是一个数；\\(\\gamma\\) 与终端惩罚是风险偏好与限额的翻译，不是可回归的量。缝填错了，错误会伪装成模型错误：抄论文表格的 \\(\\kappa\\) 在自己的标的上差一个量级，报价不是远到没有成交，就是近到被随便捡走。</p><p>更隐蔽的是时间结构。\\(A,\\kappa,\\sigma\\) 随日内时段、波动体制与消息日历漂移，全天一套参数等于假设开盘竞价与午后薄簿是同一个市场。参数缝的完整表述因此是：<strong>哪些参数点-in-time 估计，哪些由偏好与限额反推，哪些随日历调度。</strong></p><h3 id="三类参数三种来源" tabindex="-1">三类参数三种来源 <a class="header-anchor" href="#三类参数三种来源" aria-label="Permalink to &quot;三类参数三种来源&quot;">​</a></h3><p>可估计的（\\(A,\\kappa,\\sigma\\)）：用自己的限价成交、改单与撤单日志，滚动窗口内按距离分桶拟合强度；\\(\\sigma\\) 用事件时间或短窗已实现波动，剔除开盘与尾盘的机制段。反推的（\\(\\gamma\\)、终端惩罚）：从风险预算来——限额给定后，等效的风险厌恶或惩罚系数是会计选择，不是统计估计。调度的（时段修正）：开盘与尾盘放大惩罚、缩窄 \\(Q\\)，午盘恢复；非平稳写进日历规则，不让一套参数硬扛。</p><p><span class="marginnote">数字实例：\\(\\kappa\\) 是报价距离的衰减率——离中点远 1 分钱，成交强度乘 \\(e^{-\\kappa\\times 0.01}\\)。\\(\\kappa=100\\) 时强度掉到约 37%，\\(\\kappa=1\\) 时几乎不衰减：两者的报价宽度可以一模一样，成交频率却差一个数量级。抄错 \\(\\kappa\\)，不是没成交，就是被随便捡走。</span></p><p><span class="marginnote">\\(A\\) 与 \\(\\kappa\\) 必须成对重估：同一批日志里只换 \\(A\\) 不动 \\(\\kappa\\)，等于把整条强度曲线放大或压扁——成交会系统性偏多或偏少，而单看报价宽度毫无异常。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>上线是一条灰度链：影子报价（不挂真单，用市场对面模拟自己的成交与损益）、小规模实盘（限品种限单量）、全量；影子模式测不了自己成交对簿与队列的影响，后两步不可省。回测与实验走<a href="/quant/research-sim-prod">研究、模拟、实盘隔离</a>的快照口径，参数版本与快照一起冻结。费率进现金跳：每笔成交的增量是价差减 taker 费加 maker 回扣，见 <a href="/quant/maker-taker">maker-taker</a>；跨收费方案的场所不可复用参数。</p><p><span class="marginnote">常见误区：「影子报价跑得好，直接上全量。」影子模式里你的单子不会真的排队、也不占簿上的位置——它测不出自己成交后对簿的冲击，也测不出排队被插队的损耗。小规模实盘这一级就是用来补这两件事的，跳过它等于把上线当成回测的重放。</span></p>',13)),(t(),i(r,null,{default:e(()=>[l(B,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20LOG%5B%22%E8%87%AA%E8%BA%AB%E8%AE%A2%E5%8D%95%E4%B8%8E%E6%88%90%E4%BA%A4%E6%97%A5%E5%BF%97%22%5D%20--%3E%20FIT%5B%22%E6%BB%9A%E5%8A%A8%E6%8B%9F%E5%90%88%20A%20%E4%B8%8E%20%CE%BA%22%5D%0A%20%20PX%5B%22%E8%A1%8C%E6%83%85%22%5D%20--%3E%20VOL%5B%22%E7%9F%AD%E7%AA%97%20%CF%83%EF%BC%8C%E4%BA%8B%E4%BB%B6%E6%97%B6%E9%97%B4%22%5D%0A%20%20LIM%5B%22%E9%99%90%E9%A2%9D%E4%B8%8E%E9%A3%8E%E9%99%A9%E9%A2%84%E7%AE%97%22%5D%20--%3E%20GAMMA%5B%22%CE%B3%20%E4%B8%8E%E7%BB%88%E7%AB%AF%E6%83%A9%E7%BD%9A%22%5D%0A%20%20FIT%20--%3E%20CFG%5B%22%E6%8A%A5%E4%BB%B7%E9%85%8D%E7%BD%AE%EF%BC%9A%E5%AE%BD%E5%BA%A6%E5%8A%A0%E5%81%8F%E5%BA%A6%22%5D%0A%20%20VOL%20--%3E%20CFG%0A%20%20GAMMA%20--%3E%20CFG%0A%20%20CFG%20--%3E%20SHADOW%5B%22%E5%BD%B1%E5%AD%90%E6%8A%A5%E4%BB%B7%22%5D%0A%20%20SHADOW%20--%3E%20PILOT%5B%22%E5%B0%8F%E8%A7%84%E6%A8%A1%E5%AE%9E%E7%9B%98%22%5D%0A%20%20PILOT%20--%3E%20PROD%5B%22%E5%85%A8%E9%87%8F%EF%BC%8C%E5%8F%82%E6%95%B0%E7%89%88%E6%9C%AC%E5%86%BB%E7%BB%93%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=A("h2",{id:"机制",tabindex:"-1"},[E("机制 "),A("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=A("p",null,[E("模型在生产里的角色是"),A("strong",null,"分解器"),E("而不是预测器。GLFT 的小库存近似给出「线性库存偏度加波动目标价差」，多数生产实现正是这一结构。分解的价值在于错误可定位：价差收入持续低于模型，先查强度项是否过时；实现价差频繁为负，是毒性问题而非参数问题；库存方差超预算，是偏度系数或限额翻译错了。把每个损失模式对到具体参数，是上一课判据口径的延续。")],-1)),(t(),i(r,null,{default:e(()=>[l(B,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20SYM1%5B%22%E4%BB%B7%E5%B7%AE%E6%94%B6%E5%85%A5%E6%8C%81%E7%BB%AD%E4%BD%8E%E4%BA%8E%E6%A8%A1%E5%9E%8B%22%5D%20--%3E%20C1%5B%22%E6%9F%A5%E5%BC%BA%E5%BA%A6%E9%A1%B9%EF%BC%9AA%20%E4%B8%8E%20%CE%BA%20%E6%98%AF%E5%90%A6%E8%BF%87%E6%97%B6%22%5D%0A%20%20SYM2%5B%22%E5%AE%9E%E7%8E%B0%E4%BB%B7%E5%B7%AE%E9%A2%91%E7%B9%81%E4%B8%BA%E8%B4%9F%22%5D%20--%3E%20C2%5B%22%E6%AF%92%E6%80%A7%E9%97%AE%E9%A2%98%EF%BC%8C%E4%B8%8D%E6%98%AF%E5%8F%82%E6%95%B0%E9%97%AE%E9%A2%98%22%5D%0A%20%20SYM3%5B%22%E5%BA%93%E5%AD%98%E6%96%B9%E5%B7%AE%E8%B6%85%E9%A2%84%E7%AE%97%22%5D%20--%3E%20C3%5B%22%E5%81%8F%E5%BA%A6%E7%B3%BB%E6%95%B0%E6%88%96%E9%99%90%E9%A2%9D%E7%BF%BB%E8%AF%91%E9%94%99%E4%BA%86%22%5D%0A%20%20SYM4%5B%22%E5%BA%93%E5%AD%98%E5%9B%9E%E5%A4%8D%E6%97%B6%E9%97%B4%E5%8F%98%E9%95%BF%22%5D%20--%3E%20C4%5B%22%E6%88%90%E5%AF%B9%E9%87%8D%E4%BC%B0%20A%20%E4%B8%8E%20%CE%BA%22%5D%0A%20%20C1%20--%3E%20FIX%5B%22%E6%8A%8A%E6%8D%9F%E5%A4%B1%E6%A8%A1%E5%BC%8F%E5%AF%B9%E5%88%B0%E5%8F%82%E6%95%B0%EF%BC%8C%E5%86%8D%E4%BF%AE%E5%A4%8D%22%5D%0A%20%20C2%20--%3E%20FIX%0A%20%20C3%20--%3E%20FIX%0A%20%20C4%20--%3E%20FIX%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=n('<p>参数漂移靠监控发现而不是等重训：实际成交率偏离目标强度、库存回复时间变长，都是 \\(A,\\kappa\\) 过时的征兆；监控闭环是后面毒性检测与归因两课的对象。</p><p><span class="marginnote">直觉类比：模型不是自动导航，而是体检报告上的参考区间——报价赚不够时，它帮你说清「坏的是哪一格」：强度衰减、波动项还是风险厌恶。把模型当预测器、直接抄论文参数下单，就像照抄别人的体检单开药；单子越漂亮，亏得越整齐。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>指数强度与指数效用是为了闭式；强度若依赖队列长度，应回到数值解或把闭式当初值，见<a href="/quant/fill-probability">排队与成交概率</a>。竞争性报价与消息延迟不在模型里：最优距离是在对手不变的假设下算的。校准窗口内有熔断或停牌时，强度与 \\(\\sigma\\) 都要切段。本课只解决「参数从哪来」；毒性在线发现、限额、降风险依次是后课的缺口。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>理论给结构与分解：宽度为强度项加风险项，偏度随库存；实盘工作是把参数填对并保持新鲜。</li><li>参数三分类：\\(A,\\kappa,\\sigma\\) 点-in-time 估计；\\(\\gamma\\) 与惩罚由限额与预算反推；时段修正走日历调度。</li><li>\\(A\\) 与 \\(\\kappa\\) 成对重估；费率进现金跳，跨收费方案不可复用参数。</li><li>上线走影子、小规模、全量的灰度链，参数版本与快照冻结。</li><li>模型是分解器：损失模式对到具体参数，才谈得上修复。</li><li>出处：Avellaneda and Stoikov, <em>Quantitative Finance</em>, 2008；Guéant, Lehalle and Fernandez-Tapia, <em>Mathematics and Financial Economics</em>, 2013；Ho and Stoll, <em>Journal of Financial Economics</em>, 1981。</li></ul>',6))])}const f=o(m,[["render",d]]);export{C as __pageData,f as default};
